#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i < result.len() ==> result[i] == m[(m.len() - 1 - i) as int],
{
    let n: usize = m.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            result.len() == i,
            i <= n,
            forall|j: int|
                0 <= j < i ==> result[j] == m[(n - 1 - j as usize) as int],
        decreases n - i
    {
        // push element from the end of m
        result.push(m[n - 1 - i]);

        // After the push, result.len() == i + 1, and the new element satisfies the mapping.
        assert(result[i as int] == m[(n - 1 - i) as int]);

        i = i + 1;
    }

    result
}

} // verus!